krpano.action:

set(landmark_subtitle_h, 22);

addhotspot(landmark_%1_dot);
set(hotspot[landmark_%1_dot].type, text);
set(hotspot[landmark_%1_dot].html, '');
set(hotspot[landmark_%1_dot].ath, %3);
set(hotspot[landmark_%1_dot].atv, 0.0);
set(hotspot[landmark_%1_dot].edge, center);
set(hotspot[landmark_%1_dot].width, 12);
set(hotspot[landmark_%1_dot].height, 12);
