addhotspot(landmark_%1_ripple);
set(hotspot[landmark_%1_ripple].type, text);
set(hotspot[landmark_%1_ripple].html, '');
set(hotspot[landmark_%1_ripple].ath, %3);
set(hotspot[landmark_%1_ripple].atv, 0.0);
