set(hotspot[landmark_%1_line].width, 2);
set(hotspot[landmark_%1_line].height, 0);
set(hotspot[landmark_%1_line].revealheight, %4);
set(hotspot[landmark_%1_line].bg, true);
set(hotspot[landmark_%1_line].bgcolor, 0xFF1483);
set(hotspot[landmark_%1_line].bgalpha, 1);
set(hotspot[landmark_%1_line].zorder, 598);
set(hotspot[landmark_%1_line].enabled, false);

addhotspot(landmark_%1_title);
set(hotspot[landmark_%1_title].type, text);
set(hotspot[landmark_%1_title].html, '%2');
set(hotspot[landmark_%1_title].ath, %3);
set(hotspot[landmark_%1_title].atv, 0.0);

set(hotspot[landmark_%1_title].edge, leftbottom);
set(hotspot[landmark_%1_title].oy, calc(0-(%4+6+landmark_subtitle_h)));

set(hotspot[landmark_%1_title].width, 1);
set(hotspot[landmark_%1_title].height, 30);
set(hotspot[landmark_%1_title].wordwrap, false);
set(hotspot[landmark_%1_title].bg, true);
set(hotspot[landmark_%1_title].bgcolor, 0x1D7A3C);
set(hotspot[landmark_%1_title].bgalpha, 0.95);

set(hotspot[landmark_%1_title].css, 'font-family:Arial, Helvetica, sans-serif; font-size:13px; color:#FFFFFF; font-weight:bold; text-align:left; line-height:30px; padding-left:10px; padding-right:10px; white-space:nowrap;');
set(hotspot[landmark_%1_title].alpha, 0);
set(hotspot[landmark_%1_title].zorder, 600);
set(hotspot[landmark_%1_title].enabled, false);
js(landmark_measureLabel('%1', '%2'));


addhotspot(landmark_%1_subtitle);
set(hotspot[landmark_%1_subtitle].type, text);
set(hotspot[landmark_%1_subtitle].html, '%5');
set(hotspot[landmark_%1_subtitle].ath, %3);
set(hotspot[landmark_%1_subtitle].atv, 0.0);
set(hotspot[landmark_%1_subtitle].edge, leftbottom);
set(hotspot[landmark_%1_subtitle].oy, calc(0-(%4+6)));
set(hotspot[landmark_%1_subtitle].width, 1);
set(hotspot[landmark_%1_subtitle].height, landmark_subtitle_h);
set(hotspot[landmark_%1_subtitle].wordwrap, false);
set(hotspot[landmark_%1_subtitle].bg, true);
set(hotspot[landmark_%1_subtitle].bgcolor, 0x6E6DA8);
set(hotspot[landmark_%1_subtitle].bgalpha, 0.95);
set(hotspot[landmark_%1_subtitle].css, 'font-family:Arial, Helvetica, sans-serif; font-size:12px; color:#FFFFFF; font-weight:bold; text-align:left; line-height:22px; padding-left:10px; padding-right:10px; white-space:nowrap; overflow:hidden;');
set(hotspot[landmark_%1_subtitle].alpha, 0);
set(hotspot[landmark_%1_subtitle].zorder, 600);
set(hotspot[landmark_%1_subtitle].enabled, false);

if('%5' != '',
	set(hotspot[landmark_%1_subtitle].hastime, true);
	js(landmark_measureSubtitle('%1', '%5'));
,
	set(hotspot[landmark_%1_subtitle].hastime, false);
	set(hotspot[landmark_%1_subtitle].revealwidth, 1);
);

set(row_y, calc(8 + landmark_count*46));

addlayer(landmark_%1_gui_dot);
set(layer[landmark_%1_gui_dot].parent, landmarks_gui_panel);
set(layer[landmark_%1_gui_dot].type, text);
set(layer[landmark_%1_gui_dot].align, lefttop);
set(layer[landmark_%1_gui_dot].x, 14);
set(layer[landmark_%1_gui_dot].y, calc(row_y+5));
set(layer[landmark_%1_gui_dot].width, 14);
set(layer[landmark_%1_gui_dot].height, 14);
set(layer[landmark_%1_gui_dot].bg, true);
set(layer[landmark_%1_gui_dot].bgcolor, 0x8A93A0);
set(layer[landmark_%1_gui_dot].bgroundedge, 7);

addlayer(landmark_%1_gui_label);
set(layer[landmark_%1_gui_label].parent, landmarks_gui_panel);
set(layer[landmark_%1_gui_label].type, text);
set(layer[landmark_%1_gui_label].align, lefttop);
set(layer[landmark_%1_gui_label].x, 38);
set(layer[landmark_%1_gui_label].y, calc(row_y-1));
set(layer[landmark_%1_gui_label].width, 190);
set(layer[landmark_%1_gui_label].height, 18);
set(layer[landmark_%1_gui_label].html, '%2');
set(layer[landmark_%1_gui_label].css, 'color:#FFFFFF;font-family:Arial;font-size:12px;font-weight:bold;');

addlayer(landmark_%1_gui_status);
set(layer[landmark_%1_gui_status].parent, landmarks_gui_panel);
set(layer[landmark_%1_gui_status].type, text);
set(layer[landmark_%1_gui_status].align, lefttop);
set(layer[landmark_%1_gui_status].x, 38);
set(layer[landmark_%1_gui_status].y, calc(row_y+18));
set(layer[landmark_%1_gui_status].width, 190);
set(layer[landmark_%1_gui_status].height, 18);
set(layer[landmark_%1_gui_status].html, 'checking');
set(layer[landmark_%1_gui_status].css, 'color:#9FB3C8;font-family:Arial;font-size:11px;');

set(landmark_count, calc(landmark_count+1));
set(layer[landmarks_gui_panel].height, calc(8 + landmark_count*46));

set(landmark_%1_revealed, false);
landmark_pulse_ripple(%1);

set(hotspot[landmark_%1_title].revealwidth, %2);
set(hotspot[landmark_%1_title].width, 1);
set(hotspot[landmark_%1_title].alpha, 0);
set(hotspot[landmark_%1_title].css, 'font-family:Arial, Helvetica, sans-serif; font-size:13px; color:#FFFFFF; font-weight:bold; text-align:left; line-height:30px; padding-left:10px; padding-right:10px; white-space:nowrap; overflow:hidden;');

if(hotspot[landmark_%1_title].revealwidth == null OR hotspot[landmark_%1_subtitle].revealwidth == null,
	delayedcall(0.1, landmark_reveal_label(%1));
,
	stoptween(hotspot[landmark_%1_title].width);
	stoptween(hotspot[landmark_%1_subtitle].width);
	set(hotspot[landmark_%1_title].width, 1);
	set(hotspot[landmark_%1_subtitle].width, 1);
	set(hotspot[landmark_%1_title].alpha, 1);

	if(hotspot[landmark_%1_subtitle].hastime == true,
		set(hotspot[landmark_%1_subtitle].alpha, 1);
	);
	set(landmark_%1_label_dur, calc(max(0.25, min(1.1, get(hotspot[landmark_%1_title].revealwidth) / 260))));
	tween(hotspot[landmark_%1_title].width, get(hotspot[landmark_%1_title].revealwidth), landmark_%1_label_dur, easeOutQuad);
	tween(hotspot[landmark_%1_subtitle].width, get(hotspot[landmark_%1_subtitle].revealwidth), landmark_%1_label_dur, easeOutQuad);
);

stoptween(hotspot[landmark_%1_title].width);
stoptween(hotspot[landmark_%1_subtitle].width);
set(landmark_%1_label_dur, calc(max(0.2, min(0.9, get(hotspot[landmark_%1_title].revealwidth) / 300))));
tween(hotspot[landmark_%1_title].width, 1, landmark_%1_label_dur, easeInQuad, landmark_finish_hide(%1));
tween(hotspot[landmark_%1_subtitle].width, 1, landmark_%1_label_dur, easeInQuad);

stoptween(hotspot[landmark_%1_line].height);
set(landmark_%1_line_dur, calc(max(0.2, min(0.9, get(hotspot[landmark_%1_line].revealheight) / 300))));
tween(hotspot[landmark_%1_line].height, 0, landmark_%1_line_dur, easeInQuad);

set(landmark_%1_diff,  calc(abs(adjust360(view.hlookat - hotspot[landmark_%1_dot].ath))));
set(landmark_%1_vdiff, calc(abs(view.vlookat - hotspot[landmark_%1_dot].atv)));


set(landmark_%1_trigger_h, calc(view.fov * 0.5 * 0.28));
set(landmark_%1_trigger_v, calc(view.vfov * 0.5 * 0.75));


if(landmark_%1_revealed == true,
	set(landmark_%1_onscreen, calc((landmark_%1_diff LT (landmark_%1_trigger_h + 2)) AND (landmark_%1_vdiff LT (landmark_%1_trigger_v + 2))));
,
	set(landmark_%1_onscreen, calc((landmark_%1_diff LT (landmark_%1_trigger_h - 2)) AND (landmark_%1_vdiff LT (landmark_%1_trigger_v - 2))));
);

if(landmark_%1_onscreen == true,
	if(landmark_%1_revealed != true,
		set(landmark_%1_revealed, true);


		stoptween(hotspot[landmark_%1_title].width);
		hotspot[landmark_%1_title].width = 1;
		set(hotspot[landmark_%1_title].alpha, 0);
		stoptween(hotspot[landmark_%1_subtitle].width);
		hotspot[landmark_%1_subtitle].width = 1;
		set(hotspot[landmark_%1_subtitle].alpha, 0);
		stoptween(hotspot[landmark_%1_line].height);
		hotspot[landmark_%1_line].height = 0;
		set(landmark_%1_line_dur, calc(max(0.25, min(1.1, get(hotspot[landmark_%1_line].revealheight) / 260))));
		tween(hotspot[landmark_%1_line].height, get(hotspot[landmark_%1_line].revealheight), landmark_%1_line_dur, easeOutQuad, landmark_reveal_label(%1));
	);

	set(layer[landmark_%1_gui_dot].bgcolor, 0x34C759);
	set(layer[landmark_%1_gui_status].html, calc('On screen, FOV ' + roundval(view.fov, 0)));
	set(layer[landmark_%1_gui_status].css, 'color:#34C759;font-family:Arial;font-size:11px;font-weight:bold;');
,
	if(landmark_%1_revealed != false,
		set(landmark_%1_revealed, false);


		stoptween(hotspot[landmark_%1_line].height);
		landmark_hide_label(%1);
	);

	set(layer[landmark_%1_gui_dot].bgcolor, 0x8A93A0);
	set(layer[landmark_%1_gui_status].html, calc('Off screen, FOV ' + roundval(view.fov, 0)));
	set(layer[landmark_%1_gui_status].css, 'color:#9FB3C8;font-family:Arial;font-size:11px;');
);


